import sys

def main():
    n = int(sys.stdin.read().split()[0])
    out = []
    for i in range(1, n + 1):
        out.append('*' * i)
    for i in range(1, n + 1):
        out.append(' ' * (n - i) + '*' * (2 * i - 1))
    for i in range(1, n + 1):
        out.append(' '.join(str(k) for k in range(1, i + 1)))
    print('\n'.join(out))

